        eb.or([
          eb("ordinal", ">", Number(after[0])),
          eb.and([eb("ordinal", "=", Number(after[0])), eb("id", ">", String(after[1]))]),
        ]),
      );
    const rows = await q
      .orderBy("ordinal")
      .orderBy("id")
      .limit(query.limit + 1)
